    // 1. Null pointer check
    if ((wheel == NULL) || (next_wheel == NULL) || (next_momentum == NULL) || (saturated == NULL)) {
        return ADCS_E_NULL;
    }

    // 2. Finite checks for all inputs
    if ((!adcs_is_finite_vec3(&wheel->axis_body)) ||
        (!isfinite(wheel->inertia_kg_m2)) ||
        (!isfinite(wheel->speed_rad_s)) ||
        (!isfinite(motor_torque)) ||
        (!isfinite(dt)) ||
        (!isfinite(speed_limit))) {
        return ADCS_E_NOT_FINITE;
    }

    // 3. Range/Legal checks: Inertia > 0, dt >= 0, speed_limit > 0, axis norm > epsilon
    if (wheel->inertia_kg_m2 <= 0.0) {
        return ADCS_E_RANGE;
    }
    if (dt < 0.0) {
        return ADCS_E_RANGE;
    }
    if (speed_limit <= 0.0) {
        return ADCS_E_RANGE;
    }

    double axis_norm = adcs_vec3_norm(&wheel->axis_body);
    if (axis_norm <= ADCS_EPS_NORM) {
        return ADCS_E_RANGE;
    }

    // 4. Normalize axis
    adcs_vec3_t a = adcs_vec3_scale(&wheel->axis_body, 1.0 / axis_norm);

    // 5. Compute unclamped speed: omega + torque * dt / J
    double omega_unclamped = wheel->speed_rad_s + (motor_torque * dt) / wheel->inertia_kg_m2;

    // 6. Check saturation: strictly exceeds limit
    if (fabs(omega_unclamped) > speed_limit) {
        *saturated = 1;
    } else {
        *saturated = 0;
    }

    // 7. Clamp speed magnitude to [-speed_limit, +speed_limit]
    double omega_next;
    if (omega_unclamped > speed_limit) {
        omega_next = speed_limit;
    } else if (omega_unclamped < -speed_limit) {
        omega_next = -speed_limit;
    } else {
        omega_next = omega_unclamped;
    }

    // 8. Update next_wheel record
    next_wheel->axis_body = a;
    next_wheel->inertia_kg_m2 = wheel->inertia_kg_m2;
    next_wheel->speed_rad_s = omega_next;

    // 9. Map scalar angular momentum onto body axis: h_next = J * omega_next * a
    next_momentum->x = wheel->inertia_kg_m2 * omega_next * a.x;
    next_momentum->y = wheel->inertia_kg_m2 * omega_next * a.y;
    next_momentum->z = wheel->inertia_kg_m2 * omega_next * a.z;

    // 10. Return success
    return ADCS_OK;
}

