        (!isfinite(motor_torque)) || (!isfinite(dt)) || (!isfinite(speed_limit))) {
        return ADCS_E_RANGE;
    }

    if (wheel->inertia_kg_m2 <= 0.0 || dt < 0.0 || speed_limit <= 0.0) {
        return ADCS_E_RANGE;
    }

    double norm = adcs_vec3_norm(&wheel->axis_body);
    if (norm <= 1e-12) {
        return ADCS_E_RANGE;
    }

    adcs_vec3_t normalized_axis;
    adcs_status_t stat = adcs_vec3_normalize(&wheel->axis_body, 1e-12, &normalized_axis);
    if (stat != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    double omega_next_unclamped = wheel->speed_rad_s + (motor_torque * dt) / wheel->inertia_kg_m2;

    if (fabs(omega_next_unclamped) > speed_limit) {
        *saturated = 1;
    } else {
        *saturated = 0;
    }

    double omega_next = ADCS_CLAMP(omega_next_unclamped, -speed_limit, speed_limit);

    next_wheel->axis_body = normalized_axis;
    next_wheel->inertia_kg_m2 = wheel->inertia_kg_m2;
    next_wheel->speed_rad_s = omega_next;

    double h_mag = wheel->inertia_kg_m2 * omega_next;
    *next_momentum = adcs_vec3_scale(&normalized_axis, h_mag);

    return ADCS_OK;
}

